function mergeFlexible(){
  if(!state.selected.length)return toast("병합하거나 색칠할 학점 셀을 선택하세요");
  if(state.selected.some(item=>item.field)){
    merge();
    if(!state.selected.length){state.selectionMode=false;render()}
    return;
  }
  const columns=[...new Set(state.selected.map(item=>item.column))];
  if(columns.length!==1)return toast("같은 학기 열의 세로 셀만 선택하세요");
  const column=columns[0],indices=[...new Set(state.selected.map(item=>rowIndex(item.rowId)).filter(index=>index>=0))].sort((a,b)=>a-b);
  if(!indices.length)return toast("학점 셀을 선택하세요");
  const segments=[];
  indices.forEach(index=>{const last=segments.at(-1);if(last&&index===last.at(-1)+1)last.push(index);else segments.push([index])});
  remember();
  const color="#fff4d8",choiceGroupId=uid(),mergeable=segments.filter(segment=>segment.length>1),primary=mergeable[0],totalCredits=indices.reduce((sum,index)=>sum+effectiveCredit(index,column),0);
  state.creditHighlights=(state.creditHighlights||[]).filter(item=>item.column!==column||!indices.includes(rowIndex(item.rowId)));
  state.merges=state.merges.filter(item=>item.column!==column||!indices.some(index=>index>=rowIndex(item.startId)&&index<=rowIndex(item.endId)));
  segments.forEach(segment=>{
    if(segment.length===1){const originalValue=state.rows[segment[0]].credits[column]??"";state.rows[segment[0]].credits[column]="";state.creditHighlights.push({rowId:state.rows[segment[0]].id,column,color,choiceGroupId,originalValue});return}
    const isPrimary=segment===primary;
    state.merges.push({column,startId:state.rows[segment[0]].id,endId:state.rows[segment.at(-1)].id,pick:1,choiceCount:indices.length,totalCredits:isPrimary?(totalCredits||""):"",color,choiceGroupId,isPrimary});
    segment.slice(isPrimary?1:0).forEach(index=>state.rows[index].credits[column]="");
  });
  state.selected=[];state.selectionMode=false;render();
  toast(mergeable.length?`${mergeable.length}개 연속 구간을 병합했습니다`:"선택한 단일 셀에 선택군 색상을 표시했습니다");
}

function unmergeFlexible(){
  const creditSelections=state.selected.filter(item=>!item.field);
  const groupIds=new Set();
  creditSelections.forEach(item=>{
    const merged=mergeAt(item.rowId,item.column),highlight=(state.creditHighlights||[]).find(entry=>entry.rowId===item.rowId&&entry.column===item.column);
    if(merged?.choiceGroupId)groupIds.add(merged.choiceGroupId);
    if(highlight?.choiceGroupId)groupIds.add(highlight.choiceGroupId);
  });
  if(!groupIds.size)return unmerge();
  remember();
  groupIds.forEach(groupId=>{
    const primary=state.merges.find(item=>item.choiceGroupId===groupId&&item.isPrimary!==false);
    if(primary){const row=state.rows[rowIndex(primary.startId)];if(row)row.credits[primary.column]=primary.totalCredits??""}
    (state.creditHighlights||[]).filter(item=>item.choiceGroupId===groupId).forEach(item=>{const row=state.rows[rowIndex(item.rowId)];if(row)row.credits[item.column]=item.originalValue??""});
  });
  state.merges=state.merges.filter(item=>!groupIds.has(item.choiceGroupId));
  state.creditHighlights=(state.creditHighlights||[]).filter(item=>!groupIds.has(item.choiceGroupId));
  state.selected=[];render();toast("선택군 병합과 색상을 해제했습니다");
}
